/**
 * Journal slugs are generated by Go and returned by the detail API. Do not
 * reimplement Unicode case mapping in JavaScript: `ΟΣ` and `İX` produce
 * different lower-case rune sequences in the two runtimes.
 */
export function journalCanonicalPath(id: number, slug?: string): string {
  const normalized = slug?.trim();
  return normalized
    ? `/journal/${id}/${encodeURIComponent(normalized)}`
    : `/journal/${id}`;
}
